/// Where a theme's content-layer backgrounds come from. `system` uses the system backgrounds instead of theme paper.
public enum ThemeSurfaces: String, Sendable {
    case theme, system
}

/// The colors a theme may change. The raw value is the asset-name suffix. The `jade` names are historical: they mean the model color.
public enum ThemeRole: String, CaseIterable, Sendable {
    case chrome = "Chrome"
    case surface = "Surface"
    case raised = "Raised"
    case sunken = "Sunken"
    case line = "Line"
    case line2 = "Line2"
    case control = "Control"
    case ink = "Ink"
    case ink2 = "Ink2"
    case ink3 = "Ink3"
    case youWave = "YouWave"
    case jade = "Jade"
    case jadeWave = "JadeWave"
    case jadeSoft = "JadeSoft"
    case onJade = "OnJade"
    case userBubble = "UserBubble"
}

public struct Theme: Identifiable, Hashable, Sendable {
    public let id: String
    public let order: Int
    public let surfaces: ThemeSurfaces
    let assetPrefix: String

    /// The Asset Catalog color name, for example `CeladonSurface`.
    public func assetName(_ role: ThemeRole) -> String { assetPrefix + role.rawValue }
}

public enum ThemeCatalog {
    public static let defaultID = "celadon"

    /// Sorted by `order`. Settings show this list; no view keeps its own.
    public static let all: [Theme] = [
        Theme(id: "plain", order: 1, surfaces: .system, assetPrefix: "Plain"),
        Theme(id: "celadon", order: 2, surfaces: .theme, assetPrefix: "Celadon"),
        Theme(id: "xuan", order: 3, surfaces: .theme, assetPrefix: "Xuan"),
        Theme(id: "indigo", order: 4, surfaces: .theme, assetPrefix: "Indigo"),
        Theme(id: "wisteria", order: 5, surfaces: .theme, assetPrefix: "Wisteria"),
        Theme(id: "lab", order: 6, surfaces: .theme, assetPrefix: "Lab"),
